-- file: functions/_private/is_final_scoring_week.sql
-- _is_final_scoring_week: the single definition of "this round is the season finale" --
-- the round the unlimited-All-In exemption (settings.final_week_unlimited_allin) applies to.
--
-- ADR-0016 boundary 2: whether a round counts is decided exclusively by `is_scoring`, never
-- by the sign of `week_number`. The finale is therefore the highest `week_number` among the
-- season's SCORING weeks. lock_pick and lock_pick_all_groups both used a bare
-- `max(week_number)` over every week, which is correct only while non-scoring rounds happen
-- to be numbered negatively; the practice round ADR-0016 explicitly provides for
-- (`is_scoring=false` with a non-negative `week_number`) would have stolen the exemption from
-- the real final week and handed it to a round worth nothing (#792).
--
-- One function rather than the same predicate mirrored into each caller: the two RPCs carried
-- identical copies and drifted together, so the rule now changes in one place -- the same
-- shape as _participation_start (ADR-0037) and the #789 recap gate.
--
-- Returns false -- never null -- for an unknown week, for a non-scoring round, and for a
-- season with no scoring weeks at all. Callers use the result directly inside an `and`, where
-- a null would make the whole guard null and silently switch the once-per-week All-In rule
-- off, so false (enforce the rule) is the safe direction.
--
-- SECURITY DEFINER on purpose, matching _participation_start: which week is the finale is a
-- gameplay-fairness fact, and a caller reading under RLS must not be able to resolve a
-- different finale than the rule intends. Callers are SECURITY INVOKER, so `authenticated`
-- needs the explicit EXECUTE grant below (ADR-0011 revokes PUBLIC).
create or replace function public._is_final_scoring_week(p_week_id int)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select coalesce(
    (
      select w.is_scoring
         and w.week_number = (
           select max(w2.week_number)
           from public.weeks w2
           where w2.season_id = w.season_id
             and w2.is_scoring
         )
      from public.weeks w
      where w.id = p_week_id
    ),
    false
  );
$$;

grant execute on function public._is_final_scoring_week(int)
  to authenticated, service_role;

-- file: functions/picks/lock_pick_all_groups.sql
create or replace function public.lock_pick_all_groups(
  p_game_id  uuid,
  p_side     public.side_enum,
  p_weight   public.weight_enum
)
returns table (
  group_id   uuid,
  ok         boolean,
  reason     text,
  locked_at  timestamptz
)
language plpgsql
security invoker
set search_path = public
as $$
#variable_conflict use_column
declare
  v_uid              uuid := auth.uid();
  v_game             public.games%rowtype;
  v_team_id          int;
  v_final_scoring_week boolean;
  v_final_week_allin boolean;
  v_now              timestamptz := now();

  v_membership       record;
  v_line_source      text;
  v_line_id          int;
  v_spread_team_id   int;
  v_spread_value     numeric;
  v_row              public.picks%rowtype;
begin
  if v_uid is null then
    raise exception 'unauthorized' using errcode = 'P0001';
  end if;

  if p_side not in ('home', 'away') then
    raise exception 'invalid side' using errcode = 'P0001';
  end if;

  -- fetch game once (shared across all groups)
  select * into v_game
  from public.games
  where id = p_game_id;

  if not found then
    raise exception 'game not found' using errcode = 'P0001';
  end if;

  -- reject edits after kickoff for the whole call
  if v_now >= v_game.commence_time then
    raise exception 'edits are not allowed after kickoff' using errcode = 'P0001';
  end if;

  v_team_id := case when p_side = 'home' then v_game.home_team_id else v_game.away_team_id end;

  -- final-week flags shared across all groups. "Final week" is the season's last SCORING
  -- week (ADR-0016 boundary 2), resolved by public._is_final_scoring_week so this rule
  -- cannot drift from lock_pick.sql.
  v_final_scoring_week := public._is_final_scoring_week(v_game.week_id);
  v_final_week_allin   := public._get_final_week_unlimited_allin();

  -- fan-out: one pick per active membership, skipping groups that fail individually
  for v_membership in
    select gm.group_id
    from public.group_memberships gm
    where gm.user_id = v_uid
      and gm.status  = 'active'
    order by gm.joined_at, gm.group_id
  loop
    begin
      -- resolve this group's line_source (defaults to 'fanduel' when not configured)
      select coalesce(gc.line_source, 'fanduel') into v_line_source
      from public.group_config gc
      where gc.group_id = v_membership.group_id;

      if not found then
        v_line_source := 'fanduel';
      end if;

      -- per-group All-In enforcement (mirrors lock_pick.sql)
      if p_weight = 'A' and not (v_final_scoring_week and v_final_week_allin) then
        if exists (
          select 1
          from public.picks p
          join public.games g2 on g2.id = p.game_id
          where p.group_id  = v_membership.group_id
            and p.user_id   = v_uid
            and g2.week_id  = v_game.week_id
            and p.weight    = 'A'
            and p.game_id  <> p_game_id
        ) then
          raise exception 'all in already used this week' using errcode = 'P0001';
        end if;
      end if;

      -- active line snapshot for this group's source (mirrors lock_pick.sql)
      select gl.id, gl.spread_team_id, gl.spread_value
        into v_line_id, v_spread_team_id, v_spread_value
      from public.game_lines gl
      where gl.game_id        = v_game.id
        and gl.source         = v_line_source
        and gl.is_active_line = true
      order by gl.fetched_at desc, gl.id desc
      limit 1;

      if not found then
        raise exception 'no active line for game % (source=%)', p_game_id, v_line_source
          using errcode = 'P0001';
      end if;

      -- upsert pick for this group (mirrors lock_pick.sql)
      with upsert as (
        insert into public.picks (
          group_id, user_id, game_id, picked_team_id, weight,
          locked_at, locked_by, locked_line_id, locked_spread_team_id, locked_spread_value
        )
        values (
          v_membership.group_id, v_uid, v_game.id, v_team_id, p_weight,
          v_now, v_uid, v_line_id, v_spread_team_id, v_spread_value
        )
        on conflict (group_id, user_id, game_id) do update
          set picked_team_id        = excluded.picked_team_id,
              weight                = excluded.weight,
              locked_at             = excluded.locked_at,
              locked_by             = excluded.locked_by,
              locked_line_id        = excluded.locked_line_id,
              locked_spread_team_id = excluded.locked_spread_team_id,
              locked_spread_value   = excluded.locked_spread_value
        returning *
      )
      select * into v_row from upsert;

      return query select v_membership.group_id, true, null::text, v_row.locked_at;

    exception when others then
      return query select v_membership.group_id, false, sqlerrm, null::timestamptz;
    end;
  end loop;
end
$$;

grant execute on function public.lock_pick_all_groups(uuid, public.side_enum, public.weight_enum)
  to authenticated, service_role;

-- file: functions/picks/lock_pick.sql
-- file: supabase/functions/lock_pick.sql
create or replace function public.lock_pick(
  p_game_id  uuid,
  p_side     public.side_enum,
  p_weight   public.weight_enum,
  p_source   text default 'fanduel'
)
returns table (
  ok boolean,
  user_id uuid,
  game_id uuid,
  picked_side public.side_enum,
  weight public.weight_enum,
  locked_at timestamptz
)
language plpgsql
security invoker
set search_path = public
as $$
#variable_conflict use_column
declare
  v_uid     uuid := auth.uid();
  v_game    public.games%rowtype;
  v_team_id int;
  v_final_scoring_week boolean;
  v_final_week_allin boolean;
  v_line_id int;
  v_spread_team_id int;
  v_spread_value numeric;
  v_now     timestamptz := now();
  v_row     public.picks%rowtype;
  v_group_id uuid;
begin
  if v_uid is null then
    raise exception 'unauthorized' using errcode = 'P0001';
  end if;

  select gm.group_id into v_group_id
  from public.group_memberships gm
  where gm.user_id = v_uid
  order by gm.joined_at, gm.group_id
  limit 1;

  if v_group_id is null then
    raise exception 'group membership not found' using errcode = 'P0001';
  end if;

  if p_side not in ('home','away') then
    raise exception 'invalid side' using errcode = 'P0001';
  end if;

  -- fetch game (no FOR UPDATE to avoid RLS "not found")
  select * into v_game
  from public.games
  where id = p_game_id;

  if not found then
    raise exception 'game not found' using errcode = 'P0001';
  end if;

  -- no edits after kickoff
  if v_now >= v_game.commence_time then
    raise exception 'edits are not allowed after kickoff' using errcode = 'P0001';
  end if;

  v_team_id := case when p_side = 'home' then v_game.home_team_id else v_game.away_team_id end;

  -- All-In (A) enforcement: once per week, unless the final-week exception is enabled.
  -- "Final week" is the season's last SCORING week (ADR-0016 boundary 2), resolved by
  -- public._is_final_scoring_week so this rule cannot drift from lock_pick_all_groups.
  v_final_scoring_week := public._is_final_scoring_week(v_game.week_id);
  v_final_week_allin   := public._get_final_week_unlimited_allin();

  if p_weight = 'A' and not (v_final_scoring_week and v_final_week_allin) then
    if exists (
      select 1
      from public.picks p
      join public.games g2 on g2.id = p.game_id
      where p.group_id = v_group_id
        and p.user_id = v_uid
        and g2.week_id = v_game.week_id
        and p.weight = 'A'
        and p.game_id <> p_game_id
    ) then
      raise exception 'all in already used this week' using errcode = 'P0001';
    end if;
  end if;

  -- active line snapshot (required)
  select gl.id, gl.spread_team_id, gl.spread_value
    into v_line_id, v_spread_team_id, v_spread_value
  from public.game_lines gl
  where gl.game_id = v_game.id
    and gl.source  = p_source
    and gl.is_active_line = true
  order by gl.fetched_at desc, gl.id desc
  limit 1;

  if not found then
    raise exception 'no active line for game % (source=%)', p_game_id, p_source using errcode = 'P0001';
  end if;

  -- upsert with snapshot stamped atomically
  with upsert as (
    insert into public.picks (
      group_id, user_id, game_id, picked_team_id, weight,
      locked_at, locked_by, locked_line_id, locked_spread_team_id, locked_spread_value
    )
    values (
      v_group_id, v_uid, v_game.id, v_team_id, p_weight,
      v_now, v_uid, v_line_id, v_spread_team_id, v_spread_value
    )
    on conflict (group_id, user_id, game_id) do update
      set picked_team_id         = excluded.picked_team_id,
          weight                 = excluded.weight,
          locked_at              = excluded.locked_at,
          locked_by              = excluded.locked_by,
          locked_line_id         = excluded.locked_line_id,
          locked_spread_team_id  = excluded.locked_spread_team_id,
          locked_spread_value    = excluded.locked_spread_value
    returning *
  )
  select * into v_row from upsert;

  return query
  select
    true as ok,
    v_row.user_id,
    v_row.game_id,
    p_side as picked_side,
    v_row.weight,
    v_row.locked_at;
end
$$;

-- make sure the signature matches exactly (schema-qualify enums)
grant execute on function public.lock_pick(uuid, public.side_enum, public.weight_enum, text)
  to authenticated, service_role;
